INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40711, 'Daniel 5:10', 'Daniel', 5, 10, 'خو کله چې د بادشاه مور د بادشاه او د هغۀ د مشيرانو شور شرابه واورېده، نو هغه د مېلمنو هال ته راننوتله. هغې ووئيل چې، ”اے بادشاه سلامت تۀ دې د تل دپاره ژوندے يې. مۀ وارخطا کېږه، ډېر مۀ زېړېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_10.mp3', '', 1761754199, 1761754199),
(40712, 'Daniel 5:11', 'Daniel', 5, 11, 'ستا په بادشاهۍ کښې يو سړے دے چې په هغۀ کښې د پاکو معبودانو روح دے. ستا د پلار په زمانه کښې په هغۀ کښې د معبودانو په شان عقل، حکمت او پوهه ښکاره شوه. نبوکدنضر بادشاه ستا پلار هغه د جادوګرو، فالګرو، نجوميانو او پېشګويانو والا مشر مقرر کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_11.mp3', '', 1761754199, 1761754199),
(40713, 'Daniel 5:12', 'Daniel', 5, 12, 'دا سړے دانيال، چا ته چې بادشاه بيلطشضر نوم ورکړو، بې‌شانه قابليت او پوهه لرى، او هغه د خوبونو په تعبير، د مشکلو دوڼو په حل کولو او د راز په خبرو څرګندولو کښې تکړه او ماهِر دے. نو دانيال راوغواړه، هغه به درته ووائى چې د دې ليکلو مطلب څۀ دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_12.mp3', '', 1761754199, 1761754199),
(40714, 'Daniel 5:13', 'Daniel', 5, 13, 'نو بيا دانيال د بادشاه حضور ته راوستلے شو، او بادشاه هغۀ ته ووئيل، ”تۀ هغه دانيال يې څۀ، څوک چې زما پلار نبوکدنضر بادشاه د يهوداه د جلاوطنو سره د يهوداه نه دلته راوستے وو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_13.mp3', '', 1761754199, 1761754199),
(40715, 'Daniel 5:14', 'Daniel', 5, 14, 'ما اورېدلى دى چې په تا کښې د خُدايانو علم دے، او ستا عقل، پوهه او خاص حِکمت ډېر لوئ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_14.mp3', '', 1761754199, 1761754199),
(40716, 'Daniel 5:15', 'Daniel', 5, 15, 'زما په وړاندې هوښياران او جادوګران راوستلے شوى وُو چې دا ليکلے شوى الفاظ ولولى او ما ته يې مطلب بيان کړى، خو هغوئ د دې مطلب بيان نۀ کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_15.mp3', '', 1761754199, 1761754199),
(40717, 'Daniel 5:16', 'Daniel', 5, 16, 'خو اوس ما دا اورېدلى دى چې تۀ تعبير ورکولے شې او مشکلې مسئلې حل کولے شې. کۀ تۀ دا ليکل لوستلے شې او ما ته د دې مطلب بيانولے شې، نو ستا د عزت دپاره به تا ته کاسنى شاهى چُوغه درواغوستلے شى او ستا په غاړه کښې به د سرو زرو هار واچولے شى، او په بادشاهۍ کښې به درته درېم لوئ مقام درکړے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_16.mp3', '', 1761754199, 1761754199),
(40718, 'Daniel 5:17', 'Daniel', 5, 17, 'نو دانيال بادشاه ته جواب ورکړو، ”قربان تحفې دې بل چا له ورکړه او يا يې ځان سره کړه. خو بيا به هم زۀ دا ليکل بادشاه ته ولولم او هغۀ ته به يې مطلب بيان کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_17.mp3', '', 1761754199, 1761754199),
(40719, 'Daniel 5:18', 'Daniel', 5, 18, 'اے بادشاه سلامت، خُدائ تعالىٰ ستا پلار نبوکدنضر ته بادشاهت، لويوالے، جلال او شان و شوکت ورکړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_18.mp3', '', 1761754199, 1761754199),
(40720, 'Daniel 5:19', 'Daniel', 5, 19, 'هغۀ، هغۀ له ډېر اوچت مقام ورکړے وو نو په دې وجه د ټولو خلقو د ټولو قومونو، او ټولو ژبو خلق د هغۀ په وړاندې د يرې نه ريږدېدل. څوک به چې هغۀ مړ کول غوښتل نو مړ به يې کړو، څوک به يې چې ژوندے پرېښودل غوښتل نو هغه به يې ژوندے پرېښودو، او چا ته به يې چې ترقى ورکول غوښتل نو هغۀ له به يې ترقى ورکړه، او څوک به يې چې عاجز کول غوښتل هغه به يې عاجز کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_19.mp3', '', 1761754199, 1761754199),
(40721, 'Daniel 5:20', 'Daniel', 5, 20, 'خو کله چې د هغۀ زړۀ مغروره شو، او کبر يې اختيار کړو، نو هغه د خپلې بادشاهۍ تخت نه کوز کړے شو او هغه د خپل عزت نه محروم کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_20.mp3', '', 1761754199, 1761754199),
(40722, 'Daniel 5:21', 'Daniel', 5, 21, 'هغه د بنيادمو د مينځ نه وشړلے شو او هغۀ ته د ځناورو عقل ورکړے شو، او هغه د ځنګلى خرو سره اوسېدو. هغۀ لکه د څاروى په شان ګياه وخوړه، او د هغۀ بدن د آسمان په پرخه باندې تر شو، ترڅو چې هغۀ دا وپېژندل چې خُدائ تعالىٰ د بنيادمو په بادشاهت باندې اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_21.mp3', '', 1761754199, 1761754199),
(40723, 'Daniel 5:22', 'Daniel', 5, 22, 'خو تا د هغۀ زويه بيلشضره، خپل ځان د هغۀ په وړاندې عاجز نۀ کړے شو، باوجود د دې چې تۀ په دې هر څۀ باندې خبر وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_22.mp3', '', 1761754199, 1761754199),
(40724, 'Daniel 5:23', 'Daniel', 5, 23, 'بلکې، تا خپل ځان د آسمانى مالِک په خلاف راپورته کړو. د هغۀ د کور جامونه او پيالۍ ستا په وړاندې راوړلے شوى دى. تا او ستا آفسرانو، ستا ښځو، او ستا وينځو په هغې کښې مے وڅښل. تا د سرو زرو او سپينو زرو، د زېړو، د اوسپنې، لرګى او د کاڼو نه د جوړو شوو معبودانو ثناء صِفت وکړو، څوک چې نۀ ليدلے شى او نۀ اورېدلے شى او نۀ پوهيږى. خو تا د هغه مالِک خُدائ عزت ونۀ کړو د چا په لاس کښې چې ستا ژوند او ستا ټولې لارې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_23.mp3', '', 1761754199, 1761754199),
(40725, 'Daniel 5:24', 'Daniel', 5, 24, 'نو په دې وجه خُدائ پاک لاس راولېږلو کوم چې دا پېغام وليکلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_24.mp3', '', 1761754199, 1761754199),
(40726, 'Daniel 5:25', 'Daniel', 5, 25, 'دا هغه پېغام دے کوم چې ليکلے شوے وو، منې، منې تقيل، فرسين.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_25.mp3', '', 1761754199, 1761754199),
(40727, 'Daniel 5:26', 'Daniel', 5, 26, 'د دې الفاظو مطلب دا دے. منې، د دې مطلب دے شمېر، خُدائ پاک ستا د بادشاهۍ ورځې شمېرلې دى او هغه يې ختمې کړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_26.mp3', '', 1761754199, 1761754199),
(40728, 'Daniel 5:27', 'Daniel', 5, 27, 'تقيل، مطلب دے وزن، تۀ په تله باندې وتللے شوې او په وزن ډېر سپک وختلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_27.mp3', '', 1761754199, 1761754199),
(40729, 'Daniel 5:28', 'Daniel', 5, 28, 'د فرسين، معنىٰ دا ده چې تقسيم، ستا بادشاهى تقسيم شوې ده او هغه ميديانو او فارسيانو ته ورکړے شوې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_28.mp3', '', 1761754199, 1761754199),
(40730, 'Daniel 5:29', 'Daniel', 5, 29, 'نو بيا د بيلشضر په حکم، دانيال ته کاسنى رنګ چُوغه ورواغوستلے شوه، د هغۀ په غاړه کښې يې د سرو زرو هار ورواچولو، او په بادشاهۍ کښې هغه د درېم اوچت مقام په توګه اعلان کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_29.mp3', '', 1761754199, 1761754199),
(40731, 'Daniel 5:30', 'Daniel', 5, 30, 'نو په هم هغه شپه بيلشضر د بابل بادشاه ووژلے شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_30.mp3', '', 1761754199, 1761754199),
(40732, 'Daniel 5:31', 'Daniel', 5, 31, 'داريوس ميدى چې د دوو شپيتو کالو وو نو بادشاهى يې ونيوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel5_verse_31.mp3', '', 1761754199, 1761754199),
(40733, 'Deuteronomy 24:1', 'Deuteronomy', 24, 1, 'فرض کړئ یو سړی د یوې انجلۍ سره واده وکړي او وروسته یې بد ایسي، ځکه چې په هغې کې یو داسې شی ګوري چې د هغه نه خوښیږي. نو هغه طلاق نامه لیکي، هغې ته یې ورکوي او د خپل کور څخه یې شړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_1.mp3', '', 1761754199, 1761754199),
(40734, 'Deuteronomy 24:2', 'Deuteronomy', 24, 2, 'بیا فرض کړئ هغه د یو بل سړي سره واده کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_2.mp3', '', 1761754199, 1761754199),
(40735, 'Deuteronomy 24:3', 'Deuteronomy', 24, 3, 'او د دوهم مېړه هم هغه ښځه نه خوښیږي، نو هغه هم طلاق نامه لیکي، هغې ته یې ورکوي او د خپل کور څخه یې شړي. یا فرض کړئ د هغې دوهم مېړه مړ کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_3.mp3', '', 1761754199, 1761754199),
(40736, 'Deuteronomy 24:4', 'Deuteronomy', 24, 4, 'په دواړو صورتونو کې دې د هغې لومړنی مېړه بیا د هغې سره واده نه کوي، ځکه چې هغه نجسه شوې ده. که چېرې هغه ورسره بیا واده وکړي، د هغوی واده به هغه ځمکه ناپاکه کړي چې خپل څښتن خدای یې درکوي او څښتن د دې کار څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_4.mp3', '', 1761754199, 1761754199),
(40737, 'Deuteronomy 24:5', 'Deuteronomy', 24, 5, 'که چېرې یو سړي نوی واده کړی وي، هغه دې جنګ یا کومې بلې وظیفې ته نه لېږل کیږي. هغه دې یو کال د وظیفې څخه معاف وي، ترڅو هغه په کور کې پاتې شي او خپله ښځه خوشحاله وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_5.mp3', '', 1761754199, 1761754199),
(40738, 'Deuteronomy 24:6', 'Deuteronomy', 24, 6, 'کله چې تاسو چاته کوم شی په پور ورکوئ، باید د هغه د مېچنې پلونه چې د غلو دانو د میده کولو دپاره ورڅخه کار اخیستل کیږي د ضمانت په توګه وانخلئ. په دې کار سره به د هغې کورنۍ هغه وسیله له منځه لاړه شي چې هغوی ورباندې د ژوندي پاتې کېدلو دپاره خواړه تیاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_6.mp3', '', 1761754199, 1761754199),
(40739, 'Deuteronomy 24:7', 'Deuteronomy', 24, 7, 'که چېرې یو کس ونیول شي چې خپل اسراییلی ورور یې تښتاوه چې هغه خپل غلام کړي یا یې د غلام په توګه خرڅ کړي، نو تښتوونکی دې ووژل شي. په دې ډول به تاسو د دې بدکارۍ څخه خلاص شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_7.mp3', '', 1761754199, 1761754199),
(40740, 'Deuteronomy 24:8', 'Deuteronomy', 24, 8, 'کله چې تاسو د پوستکي په ساري ناروغۍ اخته شئ، نو څه چې لاوي کاهنان درته وایي کټ مټ هماغسې وکړئ. د هغو لارښوونو څخه پیروي وکړئ چې ما هغوی ته ورکړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_8.mp3', '', 1761754199, 1761754199),
(40741, 'Deuteronomy 24:9', 'Deuteronomy', 24, 9, 'په یاد ساتئ کله چې تاسو د مصر څخه راوتلئ، ستاسو څښتن خدای په مریم باندې څه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_9.mp3', '', 1761754199, 1761754199),
(40742, 'Deuteronomy 24:10', 'Deuteronomy', 24, 10, 'کله چې تاسو چاته کوم شی په پور ورکوئ، د هغه کور ته د دې دپاره مه ورننوځئ چې د هغه څخه کوم شی د ضمانت په توګه واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_10.mp3', '', 1761754199, 1761754199),
(40743, 'Deuteronomy 24:11', 'Deuteronomy', 24, 11, 'دباندې انتظار وباسئ او پرېږدئ چې هغه یې په خپله تاسو ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_11.mp3', '', 1761754199, 1761754199),
(40744, 'Deuteronomy 24:12', 'Deuteronomy', 24, 12, 'فرض کړئ یو کس دومره غریب وي چې یوازېنی شی چې هغه یې کولای شي تاسو ته د ضمانت په توګه درکړي د هغه چپنه وي، نو د هغه چپنه د شپې د خپل ځان سره ونه ساتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_12.mp3', '', 1761754199, 1761754199),
(40745, 'Deuteronomy 24:13', 'Deuteronomy', 24, 13, 'هغه د لمرپرېواته څخه مخکې بېرته ورکړئ، ترڅو د هغې خاوند وکولای شي هغه واغوندي او ویده شي او د څښتن څخه ستاسو دپاره برکت وغواړي. نو دا کار به ستاسو د څښتن خدای په نظر کې نېک عمل وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_13.mp3', '', 1761754199, 1761754199),
(40746, 'Deuteronomy 24:14', 'Deuteronomy', 24, 14, 'که چېرې تاسو غریب خلک د خپل کار دپاره مزدوران ونیسئ، نو د هغوی اجوره مه ځنډوئ، که هغه اسراییلیان وي یا هغه پردي خلک چې ستاسو په ښارونو کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_14.mp3', '', 1761754199, 1761754199),
(40747, 'Deuteronomy 24:15', 'Deuteronomy', 24, 15, 'د هرې ورځې اجوره د لمرپرېواته څخه مخکې ورکوئ. هغوی خپل ژوند په نېستۍ کې تېروي او د ژوندي پاتې کېدلو دپاره پیسو ته اړتیا لري. که چېرې هغوی ته په خپل وخت سره اجوره ورنه کړئ، هغوی به ستاسو په ضد څښتن ته فریاد وکړي او تاسو به ګناهکار وګڼل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_15.mp3', '', 1761754199, 1761754199),
(40748, 'Deuteronomy 24:16', 'Deuteronomy', 24, 16, 'پلرونه دې د هغو جرمونو په خاطر نه وژل کیږي چې د هغوی اولادونو کړي وي او اولادونه دې د هغو جرمونو په خاطر نه وژل کیږي چې د هغوی پلرونو کړي وي. هرڅوک دې یوازې د هغو جرمونو دپاره ووژل شي چې هغوی په خپله کړي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_16.mp3', '', 1761754199, 1761754199),
(40749, 'Deuteronomy 24:17', 'Deuteronomy', 24, 17, 'پردي خلک او یتیمان د خپلو حقونو څخه مه محروموئ او د پور په خاطر د یوې کونډې کالي د ضمانت په توګه مه اخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_17.mp3', '', 1761754199, 1761754199),
(40750, 'Deuteronomy 24:18', 'Deuteronomy', 24, 18, 'په یاد ساتئ چې تاسو په مصر کې غلامان وئ او خپل څښتن خدای ازاد کړئ، نو ځکه زه تاسو ته دا امر کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_18.mp3', '', 1761754199, 1761754199),
(40751, 'Deuteronomy 24:19', 'Deuteronomy', 24, 19, 'کله چې تاسو خپل فصلونه لو کوئ او په پټي کې درڅخه کومه ګېډۍ پاتې شي، د هغې پسې بېرته مه ورځئ. هغه پردیو خلکو، یتیمانو او کونډو ته پرېږدئ، ترڅو ستاسو څښتن خدای ستاسو په هر کار کې برکت واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_19.mp3', '', 1761754199, 1761754199),
(40752, 'Deuteronomy 24:20', 'Deuteronomy', 24, 20, 'کله چې تاسو یوځل خپل زیتون راټول کړل، نو د پاتې شویو زیتونو پسې بېرته مه ورځئ چې هغه هم راوړئ. هغه د پردیو خلکو، یتیمانو او کونډو دپاره پرېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_20.mp3', '', 1761754199, 1761754199),
(40753, 'Deuteronomy 24:21', 'Deuteronomy', 24, 21, 'کله چې تاسو یوځل خپل انګور راټول کړل، دوهم ځل تاکونو ته مه ورځئ. کوم انګور چې پاتې وي هغه د پردیو خلکو، یتیمانو او کونډو دپاره دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_21.mp3', '', 1761754199, 1761754199),
(40754, 'Deuteronomy 24:22', 'Deuteronomy', 24, 22, 'دا خبره هېڅکله مه هېروئ چې تاسو په مصر کې غلامان وئ، نو ځکه زه تاسو ته دا حکم کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy24_verse_22.mp3', '', 1761754199, 1761754199),
(40755, 'Leviticus 5:1', 'Leviticus', 5, 1, 'په دې لاندېنیو حالتونو کې د ګناه نذرانې ضروري دي: که چېرې څوک د شاهدۍ ورکولو دپاره محکمې ته وغوښتل شي او د هغو شیانو په اړه چې هغه لیدلي یا اورېدلي دي معلومات ورنه کړي، نو هغه ته دې د خپلو بدو سزا ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_1.mp3', '', 1761754199, 1761754199),
(40756, 'Leviticus 5:2', 'Leviticus', 5, 2, 'که چېرې د چا لاس په سهوې سره د یو شي سره چې په مذهبي لحاظ ناپاک وي لکه مړ شوي حیوان سره ولګیږي، نو کله چې پوه شي چې هغه څه کړي دي، نو هغه کس ناپاکه او ګناهکار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_2.mp3', '', 1761754199, 1761754199),
(40757, 'Leviticus 5:3', 'Leviticus', 5, 3, 'که چېرې څوک په سهوې سره د انساني ناپاکۍ سره که هغه هرڅه وي ولګیږي، نو څنګه چې پوه شي چې څه یې کړي دي، هغه به ګناهکار وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_3.mp3', '', 1761754199, 1761754199),
(40758, 'Leviticus 5:4', 'Leviticus', 5, 4, 'که چېرې د یو چا فکر نه وي او قسم وخوري، مهمه نه ده چې د څه شي په هکله وي، څنګه چې ورڅخه خبر شي، نو هغه به ګناهکار وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_4.mp3', '', 1761754199, 1761754199),
(40759, 'Leviticus 5:5', 'Leviticus', 5, 5, 'کله چې څوک د دغو ګناهونو څخه یوه ګناه وکړي، هغه باید د هغې ګناه اقرار وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_5.mp3', '', 1761754199, 1761754199),
(40760, 'Leviticus 5:6', 'Leviticus', 5, 6, 'او د خپلې ګناه د جریمې په توګه باید څښتن ته د نذرانې په توګه یوه مېږه یا وزه راولي او کاهن به د هغه د ګناه دپاره کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_6.mp3', '', 1761754199, 1761754199),
(40761, 'Leviticus 5:7', 'Leviticus', 5, 7, 'که چېرې هغه کس مېږه یا وزه نه شي اخیستلی، نو څښتن ته دې د خپلې ګناه د جریمې په توګه دوه کوترې یا دوه قمري ګانې راوړي یعنې یوه د ګناه د نذرانې او بله د سوځېدونکې نذرانې دپاره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_7.mp3', '', 1761754199, 1761754199),
(40762, 'Leviticus 5:8', 'Leviticus', 5, 8, 'هغه دې کاهن ته راوړي او کاهن به لومړی یوه د ګناه د نذرانې دپاره وړاندې کړي. هغه دې په داسې طریقې سره د هغې ورمېږ تاو کړي چې سر ورڅخه بېل نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_8.mp3', '', 1761754199, 1761754199),
(40763, 'Leviticus 5:9', 'Leviticus', 5, 9, 'هغه دې د ګناه د نذرانې څخه لږه وینه د قربانۍ د ځای په اړخ کې وشیندي، پاتې وینه باید د قربانۍ د ځای په بېخ کې تویه شي. دا د ګناه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_9.mp3', '', 1761754199, 1761754199),
(40764, 'Leviticus 5:10', 'Leviticus', 5, 10, 'بیا به د مقرراتو له مخې هغه دوهمه مرغۍ د سوځېدونکې نذرانې په توګه وړاندې کړي. په دې ډول به کاهن د هغه کس د ګناه دپاره کفاره ادا کړي او هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_10.mp3', '', 1761754199, 1761754199),
(40765, 'Leviticus 5:11', 'Leviticus', 5, 11, 'که چېرې هغه کس دوه کوترې یا دوه قمري ګانې هم نه شي اخیستلی، نو د خپلې ګناه د نذرانې دپاره دې یو کیلو ګرام ښه اوړه راوړي. په هغو باندې دې د زیتونو تېل یا قیمتي خوشبویي نه اچوي، ځکه چې دا د ګناه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_11.mp3', '', 1761754199, 1761754199),
(40766, 'Leviticus 5:12', 'Leviticus', 5, 12, 'هغه باید کاهن ته راوړي، کاهن به د هغو اوړو څخه چې ټول څښتن ته وړاندې کیږي، یو موټی د نمونې په توګه راواخلي او د نورو نذرانو سره به یې د قربانۍ په ځای باندې وسوځوي. دا د ګناه د لېرې کولو نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_12.mp3', '', 1761754199, 1761754199),
(40767, 'Leviticus 5:13', 'Leviticus', 5, 13, 'په دې ډول به کاهن د هغه د ګناهونو دپاره کفاره ادا کړي او هغه به وبخښل شي. پاتې نذرانه به د غلې دانې د نذرانې په شان د کاهن وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_13.mp3', '', 1761754199, 1761754199),
(40768, 'Leviticus 5:14', 'Leviticus', 5, 14, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_14.mp3', '', 1761754199, 1761754199),
(40769, 'Leviticus 5:15', 'Leviticus', 5, 15, '«که چېرې څوک په سهوې سره هغه شیان چې څښتن ته وقف شوي دي یا د هغو بیه کاهن ته ورنه کړي، نو هغه دې د تاوان د نذرانې په توګه څښتن ته یو داسې پسه راولي چې کوم عیب په کې نه وي. د هغه بیه دې د هغو پیسو له مخې وي چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_15.mp3', '', 1761754199, 1761754199),
(40770, 'Leviticus 5:16', 'Leviticus', 5, 16, 'برسېره پردې، نوموړی باید هغه پیسې ورکړي چې د هغو په ورکولو نه دی بریالی شوی او شل فیصده دې زیاتې هم ورکړي. هغه به دا ټولې پیسې کاهن ته ورکوي. کاهن به د هغه دپاره په پسه باندې د تاوان د نذرانې په توګه کفاره ادا کړي او هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_16.mp3', '', 1761754199, 1761754199),
(40771, 'Leviticus 5:17', 'Leviticus', 5, 17, 'که چېرې څوک په سهوې سره ګناه وکړي او د څښتن د حکمونو څخه کوم حکم مات کړي، نو هغه ګناهکار دی او د هغې جرمانه به ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_17.mp3', '', 1761754199, 1761754199),
(40772, 'Leviticus 5:18', 'Leviticus', 5, 18, 'هغه دې د تاوان د نذرانې په توګه کاهن ته یو داسې پسه راولي چې کوم عیب په کې نه وي او مناسبه بیه ولري. په دې ډول به کاهن د هغه د ګناه دپاره چې په سهوې سره یې کړې ده، کفاره ادا کړي او هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_18.mp3', '', 1761754199, 1761754199),
(40773, 'Leviticus 5:19', 'Leviticus', 5, 19, 'دا د هغې ګناه دپاره د تاوان یوه نذرانه ده چې د څښتن په وړاندې یې کړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus5_verse_19.mp3', '', 1761754199, 1761754199),
(40774, 'Psalms 53:1', 'Psalms', 53, 1, 'کم‌عقلان خپلو ځانونو سره وایي چې خدای نشته هغوی ټول دي فاسد شوي او کوي ډېر بد کارونه دوی کې هېڅ یو نېک کار نه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_1.mp3', '', 1761754199, 1761754199),
(40775, 'Psalms 53:2', 'Psalms', 53, 2, 'په انسانانو له اسمانه خدای نظر ساتي خپل ترڅو وګوري کوم شته داسې عاقل چې رجوع وکړي هغه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_2.mp3', '', 1761754199, 1761754199),
(40776, 'Psalms 53:3', 'Psalms', 53, 3, 'خو هغوی ټول مرتدان شول ورسره هم فاسدان شول دوی کې هېڅ یو نېک کار نه کړي یو هم نه کړي نېک کردار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_3.mp3', '', 1761754199, 1761754199),
(40777, 'Psalms 53:4', 'Psalms', 53, 4, 'خدای کوي دغه پوښتنه: «بدکاران هېڅ نه پوهیږي؟ زما خلک داسې خوري دوی لکه وږي چې ډوډۍ خوري هېڅ دعا نه کوي ماته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_4.mp3', '', 1761754199, 1761754199),
(40778, 'Psalms 53:5', 'Psalms', 53, 5, 'خو په دوی باندې به داسې وېره راشي چې به هېڅ نه وي موجود په حقیقت کې وشیندي خدای به د هغو هډوکي چا چې د خدای قوم کلابند کړی دی دغه خلک دي خدای رد کړي نو اسراییل به پوره ماتې ورکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_5.mp3', '', 1761754199, 1761754199),
(40779, 'Psalms 53:6', 'Psalms', 53, 6, 'کاشکې راشي نجات د اسراییلو له صهیونه برکت چې کله بیا ورکړې خدایه خپل ولس ته بیا خوشحاله کورنۍ به د یعقوب شي اسراییل به په دې کار سره خوشحال شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms53_verse_6.mp3', '', 1761754199, 1761754199),
(40780, 'Zechariah 1:1', 'Zechariah', 1, 1, 'د فارس بادشاه داريوس د بادشاهۍ د دوېم کال په اتمه مياشت، د مالِک خُدائ کلام په زکرياه پېغمبر، د برکياه په زوئ چې د عدو زوئ وو نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_1.mp3', '', 1761754199, 1761754199),
(40781, 'Zechariah 1:2', 'Zechariah', 1, 2, '”ستاسو پلار نيکۀ ته مالِک خُدائ ډېر غصه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_2.mp3', '', 1761754199, 1761754199),
(40782, 'Zechariah 1:3', 'Zechariah', 1, 3, 'نو په دې وجه خلقو ته ووايه چې، مالِک خُدائ ربُ الافواج فرمائى چې ما ته راواپس شئ، او زۀ به تاسو ته راواپس شم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_3.mp3', '', 1761754199, 1761754199),
(40783, 'Zechariah 1:4', 'Zechariah', 1, 4, 'د خپل پلار نيکۀ په شان مۀ جوړېږئ، چا ته به چې پخوانو پېغمبرانو فرمائيل چې، ”مالِک خُدائ دا فرمائى چې، د خپلې بدعملۍ نه او د خپل بدعمله کارونو نه واوړئ.“ خو هغوئ به ما ته غوږ نۀ نيولو او نۀ به يې توجو راکوله، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_4.mp3', '', 1761754199, 1761754199),
(40784, 'Zechariah 1:5', 'Zechariah', 1, 5, 'خو ستاسو پلار نيکۀ اوس چرته دى؟ ولې هغوئ او پېغمبران به تر ابده ژوندى وى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_5.mp3', '', 1761754199, 1761754199),
(40785, 'Zechariah 1:6', 'Zechariah', 1, 6, 'خو هر څۀ چې ما د خپلو خِدمتګارانو پېغمبرانو په وسيله ستاسو پلار نيکۀ ته وفرمائيل، هم هغه شان وشُو لکه څنګه چې ما حکم ورکړے وو. نو بيا هغوئ توبه وويسته او وې وئيل، مالِک خُدائ ربُ الافواج مونږ سره هغه څۀ وکړل د کوم چې زمونږ طريقې او عملونه حقدار وُو، هغۀ مونږ سره هغه څۀ وکړل د څۀ کولو چې هغۀ اراده کړې وه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_6.mp3', '', 1761754199, 1761754199),
(40786, 'Zechariah 1:7', 'Zechariah', 1, 7, 'د داريوس د بادشاهۍ په دوېم کال، د يوولسمې مياشتې په څليريشتمه ورځ چې د شيباط مياشت وه، د مالِک خُدائ کلام زکرياه د برکياه په زوئ چې د عدو زوئ وو نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_7.mp3', '', 1761754199, 1761754199),
(40787, 'Zechariah 1:8', 'Zechariah', 1, 8, 'په شپه کښې ما يوه رويا وليده، او هلته زما په وړاندې يو سړے په سُور آس سور وو. هغه آس د سر درو ونو په مينځ کښې په يو تنګه وادۍ کښې ولاړ وو. د هغۀ نه شاته سرۀ، نسوارى او سپين آسونه وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_8.mp3', '', 1761754199, 1761754199),
(40788, 'Zechariah 1:9', 'Zechariah', 1, 9, 'ما تپوس وکړو، ”دا څۀ دى، زما مالِکه؟“ هغه فرښتې چې ما سره يې خبرې کولې جواب راکړو، ”زۀ به تا ته وښايم چې دا څۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_9.mp3', '', 1761754199, 1761754199),
(40789, 'Zechariah 1:10', 'Zechariah', 1, 10, 'بيا هغه سړے چې د سر درو ونو مينځ کښې ولاړ وو هغۀ جواب راکړو، ”دا هغه څوک دے چې مالِک خُدائ رالېږلے دے چې په دُنيا کښې ګشت وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_10.mp3', '', 1761754199, 1761754199),
(40790, 'Zechariah 1:11', 'Zechariah', 1, 11, 'او هغوئ د مالِک خُدائ فرښتې ته خبر ورکړو، څوک چې د سر درو ونو په مينځ کښې ولاړه وه، ”مونږ په ټوله دُنيا کښې ګشت وکړو او پته راته ولګېده چې ټوله دُنيا په آرام او امن کښې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_11.mp3', '', 1761754199, 1761754199),
(40791, 'Zechariah 1:12', 'Zechariah', 1, 12, 'بيا د مالِک خُدائ فرښتې وفرمائيل، ”مالِکه خُدايه، ربُ الافواجه، تۀ به ترڅو پورې په يروشلم او د يهوداه په علاقو رحم نۀ کوې، چا ته چې تۀ د اويا کالو نه غصه يې؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_12.mp3', '', 1761754199, 1761754199),
(40792, 'Zechariah 1:13', 'Zechariah', 1, 13, 'نو مالِک خُدائ په رحم او نرم لفظونو هغه فرښتې سره خبرې وکړې چا چې ما سره خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_13.mp3', '', 1761754199, 1761754199),
(40793, 'Zechariah 1:14', 'Zechariah', 1, 14, 'بيا هغه فرښتې چا چې ما سره خبرې کولې راته يې وفرمائيل، ”د دې کلام اعلان وکړه چې مالِک خُدائ ربُ الافواج دا فرمائى، زۀ په يروشلم او صيون ډېر زيات غېرت کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_14.mp3', '', 1761754199, 1761754199),
(40794, 'Zechariah 1:15', 'Zechariah', 1, 15, 'خو زۀ هغه نورو قومونو ته ډېر غصه يم چې په امن او سکون کښې ژوند کوى. زۀ خپلو خلقو ته لږ غصه وم، خو دې قومونو هغوئ ته زما د ارادې نه زيات نقصان ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_15.mp3', '', 1761754199, 1761754199),
(40795, 'Zechariah 1:16', 'Zechariah', 1, 16, 'په دې وجه، مالِک خُدائ دا فرمائى، زۀ به يروشلم ته واپس رحم سره راشم، او هلته به زما کور بيا آباد شى. او د ناپ تول تارونه به په يروشلم راښکلے شى، دا مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_16.mp3', '', 1761754199, 1761754199),
(40796, 'Zechariah 1:17', 'Zechariah', 1, 17, 'نو دا هم ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، زما ښارونه به بيا د برکت نه ډک شى، او مالِک خُدائ به بيا صيون له تسلى ورکړى او يروشلم به لکه د خپل ښار دوباره غوره کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_17.mp3', '', 1761754199, 1761754199),
(40797, 'Zechariah 1:18', 'Zechariah', 1, 18, 'بيا ما بره وکتل، او هلته زما په وړاندې څلور ښکرونه وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_18.mp3', '', 1761754199, 1761754199),
(40798, 'Zechariah 1:19', 'Zechariah', 1, 19, 'ما تپوس وکړو، د هغه فرښتې نه چې ما سره يې خبرې کولې، ”دا څۀ دى؟“ هغې جواب راکړو، ”دا هغه ښکرونه دى چې يهوداه، اِسرائيل او يروشلم يې خوارۀ وارۀ کړى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_19.mp3', '', 1761754199, 1761754199),
(40799, 'Zechariah 1:20', 'Zechariah', 1, 20, 'بيا مالِک خُدائ ما ته څلور لوهاران وښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_20.mp3', '', 1761754199, 1761754199),
(40800, 'Zechariah 1:21', 'Zechariah', 1, 21, 'ما ترې نه تپوس وکړو چې، ”دا څلور کسان د څۀ دپاره راروان دى؟“ نو فرښتې جواب راکړو، ”دا څلور ښکرونه هغه قومونه دى چې يهوداه يې عاجز او تس نس کړو. نو اوس دا لوهاران راغلى دى چې دا قومونه ويروى او راښکته يې کړى او د هغوئ کبر ختم کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah1_verse_21.mp3', '', 1761754199, 1761754199),
(40801, 'Psalms 64:1', 'Psalms', 64, 1, 'واوره زما اواز خدایه واوره شکایت زما خپلو دښمنانو نه وېرېږم زه وساته ژوندون زما!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_1.mp3', '', 1761754199, 1761754199),
(40802, 'Psalms 64:2', 'Psalms', 64, 2, 'وساته ما د دسیسو د بدکارانو څخه هم د شریرانو د ډلو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_2.mp3', '', 1761754199, 1761754199),
(40803, 'Psalms 64:3', 'Psalms', 64, 3, 'تېرې کوي دوی خپلې ژبې د تورو په شان دوی په ترخو خبرو لکه د غشو په شان نښه ولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_3.mp3', '', 1761754199, 1761754199),
(40804, 'Psalms 64:4', 'Psalms', 64, 4, 'په کمینونو کې دوی ولي بې‌ګناه انسانان بې له کوم ترسه ناڅاپه په هغوی باندې ګوزار کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_4.mp3', '', 1761754199, 1761754199),
(40805, 'Psalms 64:5', 'Psalms', 64, 5, 'هغوی یو بل تشویقوي په خپلو بدو دسیسو باندې دوی جوړوي داسې پلان چې په کوم ځای کې دوی دامونه کېږدي هغوی وایي چې څوک مونږ نه شي لیدلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_5.mp3', '', 1761754199, 1761754199),
(40806, 'Psalms 64:6', 'Psalms', 64, 6, 'جوړوي بد پلانونه او دوی وایي: «څومره ښه پلان مو دی جوړ کړی» څه مرموز دی د انسان زړه او دماغ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_6.mp3', '', 1761754199, 1761754199),
(40807, 'Psalms 64:7', 'Psalms', 64, 7, 'خو خدای به وولي هغوی په خپلو غشو او ناڅاپه به هغوی شي زخمیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_7.mp3', '', 1761754199, 1761754199),
(40808, 'Psalms 64:8', 'Psalms', 64, 8, 'خپلې خبرې به نابود کړي هغوی هرڅوک چې ویني هغوی کړي اشارې به په ملنډو ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_8.mp3', '', 1761754199, 1761754199),
(40809, 'Psalms 64:9', 'Psalms', 64, 9, 'انسانان به ټول وېریږي بیانوي به دوی د خدای کارونه او کړي سوچونه په هغې څه چې خدای کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_9.mp3', '', 1761754199, 1761754199),
(40810, 'Psalms 64:10', 'Psalms', 64, 10, 'څښتن چې وکړل کوم کارونه نېکان دې کاندي خوشحالي په هغو پناه دې یوسي ده ته ټول نېکان خلک دې صفتونه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms64_verse_10.mp3', '', 1761754199, 1761754199);